"use client";

import * as React from "react";
import { Toggle as TogglePrimitive } from "@base-ui/react/toggle";
import { ToggleGroup as ToggleGroupPrimitive } from "@base-ui/react/toggle-group";
import { type VariantProps } from "class-variance-authority";

import { cn } from "@/lib/utils";
import { optionTrack } from "./_shared";
import { toggleVariants } from "./toggle";

type WithClassName<P> = Omit<P, "className"> & { className?: string };

const ToggleGroupContext = React.createContext<VariantProps<typeof toggleVariants>>({});

/** Mallow ToggleGroup: a row of toggles in one lilac option track, passing its variant and size to every item. */
function ToggleGroup({
  className,
  variant,
  size,
  children,
  ...props
}: WithClassName<ToggleGroupPrimitive.Props<string>> & VariantProps<typeof toggleVariants>) {
  return (
    <ToggleGroupPrimitive
      data-slot="toggle-group"
      className={cn(
        "inline-flex flex-wrap items-center gap-1 rounded-xl p-1",
        optionTrack,
        "data-[orientation=vertical]:flex-col data-[orientation=vertical]:items-stretch data-[orientation=vertical]:rounded-2xl",
        className,
      )}
      {...props}
    >
      <ToggleGroupContext.Provider value={{ variant, size }}>{children}</ToggleGroupContext.Provider>
    </ToggleGroupPrimitive>
  );
}
ToggleGroup.displayName = "ToggleGroup";

/** One toggle inside a ToggleGroup, shown in the chosen-option tint when pressed. */
function ToggleGroupItem({
  className,
  variant,
  size,
  ...props
}: WithClassName<TogglePrimitive.Props<string>> & VariantProps<typeof toggleVariants>) {
  const context = React.useContext(ToggleGroupContext);

  return (
    <TogglePrimitive
      data-slot="toggle-group-item"
      className={cn(
        toggleVariants({ variant: context.variant ?? variant, size: context.size ?? size }),
        // Inside the group the track is shared, so an outline item drops its own.
        "not-data-[pressed]:bg-transparent not-data-[pressed]:shadow-none",
        className,
      )}
      {...props}
    />
  );
}
ToggleGroupItem.displayName = "ToggleGroupItem";

export { ToggleGroup, ToggleGroupItem };
